--[[ZAKA HUD - MESSY VERSION]]local a=game:GetService("Players")local b=game:GetService("RunService")local c=game:GetService("UserInputService")local d=game:GetService("TweenService")local e=game:GetService("Lighting")local f=game:GetService("VirtualUser")local g=a.LocalPlayer local h=workspace.CurrentCamera
local S={Aimbot=false,AimbotFOV=135,AimbotSmooth=0.14,AimbotTeamCheck=true,AimbotWallCheck=true,NPCAimbot=false,NPCAimbotFOV=145,ESP=false,ESPBox=true,ESPName=true,ESPHealth=true,ESPDistance=true,ESPTracer=false,ESPMaxDist=2600,ESPTeamCheck=false,NPCESP=false,Speed=false,SpeedValue=30,Fly=false,FlySpeed=80,Noclip=false,InfiniteJump=false,ClickTP=false,GodMode=false,InfiniteAmmo=false,VehicleSpeed=false,VehicleSpeedValue=180,Fullbright=false,FireAura=false,IceAura=false,ElectricAura=false,RainbowBody=false,AntiAFK=true}
