local function CC(ch)if CapeM then CapeM:Destroy()end if CapeC then CapeC:Disconnect()end local ts=ch:FindFirstChild("UpperTorso")or ch:FindFirstChild("Torso")if not ts then return end CapeM=Instance.new("Model")CapeM.Name="ZakaCape"local cp=Instance.new("Part")cp.Size=Vector3.new(2.3,3.5,0.15)cp.Color=Color3.fromRGB(175,15,15)cp.Material=Enum.Material.Fabric cp.CanCollide=false cp.Massless=true cp.Parent=CapeM local bd=Instance.new("Part")bd.Size=Vector3.new(2.5,3.7,0.08)bd.Color=Color3.fromRGB(255,205,40)bd.Material=Enum.Material.Neon bd.Transparency=0.28 bd.CanCollide=false bd.Massless=true bd.Parent=CapeM local bw=Instance.new("Weld")bw.Part0=cp bw.Part1=bd bw.C0=CFrame.new(0,0,0.03)bw.Parent=bd local w=Instance.new("Weld")w.Part0=ts w.Part1=cp w.C0=CFrame.new(0,0.28,1.12)*CFrame.Angles(math.rad(7),0,0)w.Parent=cp CapeM.Parent=ch local base=w.C0 CapeC=b.RenderStepped:Connect(function()if not cp or not cp.Parent then return end if Flying then w.C0=base*CFrame.Angles(math.rad(-17),math.sin(tick()*9)*0.17,0)else w.C0=base*CFrame.Angles(math.rad(4),math.sin(tick()*2.1)*0.08,0)end end)end
local function RC()if CapeC then CapeC:Disconnect()CapeC=nil end if CapeM then CapeM:Destroy()CapeM=nil end end
local function SF()if Flying then return end local ch=g.Character if not ch or not ch:FindFirstChild("HumanoidRootPart")then return end Flying=true local rt=ch.HumanoidRootPart local hm=ch:FindFirstChildOfClass("Humanoid")if hm then hm.PlatformStand=true end BV=Instance.new("BodyVelocity")BV.MaxForce=Vector3.new(9e9,9e9,9e9)BV.Parent=rt BG=Instance.new("BodyGyro")BG.MaxTorque=Vector3.new(9e9,9e9,9e9)BG.P=4e4 BG.Parent=rt CC(ch)
b:BindToRenderStep("ZakaFly",Enum.RenderPriority.Camera.Value,function()if not Flying or not rt.Parent then return end local cam=h.CFrame local dir=Vector3.zero if c:IsKeyDown(Enum.KeyCode.W)then dir=dir+cam.LookVector end if c:IsKeyDown(Enum.KeyCode.S)then dir=dir-cam.LookVector end if c:IsKeyDown(Enum.KeyCode.A)then dir=dir-cam.RightVector end if c:IsKeyDown(Enum.KeyCode.D)then dir=dir+cam.RightVector end if c:IsKeyDown(Enum.KeyCode.Space)then dir=dir+Vector3.new(0,1,0)end if c:IsKeyDown(Enum.KeyCode.LeftControl)then dir=dir-Vector3.new(0,1,0)end BV.Velocity=dir.Magnitude>0 and dir.Unit*S.FlySpeed or Vector3.zero BG.CFrame=CFrame.new(rt.Position,rt.Position+cam.LookVector)end)end
local function STF()Flying=false pcall(function()b:UnbindFromRenderStep("ZakaFly")end)if BV then BV:Destroy()end if BG then BG:Destroy()end local hm=g.Character and g.Character:FindFirstChildOfClass("Humanoid")if hm then hm.PlatformStand=false end RC()end
local function SS(v)if SpeedC then SpeedC:Disconnect()end if v then SpeedC=b.Heartbeat:Connect(function()local hm=g.Character and g.Character:FindFirstChildOfClass("Humanoid")if hm then hm.WalkSpeed=S.SpeedValue end end)else local hm=g.Character and g.Character:FindFirstChildOfClass("Humanoid")if hm then hm.WalkSpeed=16 end end end
local function SN(v)if NoclipC then NoclipC:Disconnect()end if v then NoclipC=b.Stepped:Connect(function()local ch=g.Character if ch then for _,p in ipairs(ch:GetDescendants())do if p:IsA("BasePart")then p.CanCollide=false end end end end)end end
