c.TouchTap:Connect(function(pos,gpe)if S.ClickTP and not gpe and pos[1]then local ray=h:ViewportPointToRay(pos[1].X,pos[1].Y)local hit,p=workspace:FindPartOnRayWithIgnoreList(Ray.new(ray.Origin,ray.Direction*2000),{g.Character})if hit and g.Character and g.Character:FindFirstChild("HumanoidRootPart")then g.Character.HumanoidRootPart.CFrame=CFrame.new(p+Vector3.new(0,4,0))end end end)
local function SG(v)if GodC then GodC:Disconnect()end if v then GodC=b.Heartbeat:Connect(function()local hm=g.Character and g.Character:FindFirstChildOfClass("Humanoid")if hm then hm.MaxHealth=math.huge hm.Health=math.huge end end)end end
local function SIA(st)S.InfiniteAmmo=st if st then task.spawn(function()while S.InfiniteAmmo do local ch=g.Character if ch then for _,t in ipairs(ch:GetChildren())do if t:IsA("Tool")then pcall(function()if t:FindFirstChild("Ammo")then t.Ammo.Value=999 end if t:FindFirstChild("Clip")then t.Clip.Value=999 end if t:FindFirstChild("CurrentAmmo")then t.CurrentAmmo.Value=999 end end)end end end task.wait(0.4)end end)end end
local function SVS(st)S.VehicleSpeed=st if VehC then VehC:Disconnect()end if st then VehC=b.Heartbeat:Connect(function()local hm=g.Character and g.Character:FindFirstChildOfClass("Humanoid")if hm and hm.SeatPart then local veh=hm.SeatPart.Parent if veh then pcall(function()local seat=veh:FindFirstChildWhichIsA("VehicleSeat")or veh:FindFirstChild("VehicleSeat")if seat then seat.MaxSpeed=S.VehicleSpeedValue end end)end end end)end end
local function SFBF(v)if v then e.Brightness=2.5 e.ClockTime=14 e.FogEnd=1e5 e.GlobalShadows=false else e.Brightness=1 e.FogEnd=1000 e.GlobalShadows=true end end
local function SRB(v)if RainC then RainC:Disconnect()end if v then RainC=b.RenderStepped:Connect(function()local ch=g.Character if not ch then return end local col=Color3.fromHSV(tick()%5/5,1,1)for _,p in ipairs(ch:GetDescendants())do if p:IsA("BasePart")and p.Name\~="HumanoidRootPart"then p.Color=col end end end)end end
local FOV=Drawing.new("Circle")FOV.Thickness=1.5 FOV.NumSides=64 FOV.Filled=false FOV.Color=Color3.fromRGB(0,180,255)FOV.Transparency=0.7 FOV.Visible=false
local function GCP()local cl,sh=nil,S.AimbotFOV local mp=c:GetMouseLocation()for _,pl in ipairs(a:GetPlayers())do if pl\~=g and pl.Character then local hm=pl.Character:FindFirstChildOfClass("Humanoid")local hd=pl.Character:FindFirstChild("Head")if hm and hm.Health>0 and hd then if S.AimbotTeamCheck and pl.Team==g.Team then continue end local sp,on=h:WorldToViewportPoint(hd.Position)if on then if S.AimbotWallCheck then local ry=Ray.new(h.CFrame.Position,(hd.Position-h.CFrame.Position).Unit*3000)local ht=workspace:FindPartOnRayWithIgnoreList(ry,{g.Character,h})if ht and not ht:IsDescendantOf(pl.Character)then continue end end local ds=(Vector2.new(sp.X,sp.Y)-mp).Magnitude if ds<sh then sh=ds cl=hd end end end end end return cl end
local function GCN()local cl,sh=nil,S.NPCAimbotFOV local mp=c:GetMouseLocation()for _,ob in ipairs(workspace:GetDescendants())do if ob:IsA("Model")and ob:FindFirstChildOfClass("Humanoid")and ob:FindFirstChild("Head")then if a:GetPlayerFromCharacter(ob)then continue end local hm=ob:FindFirstChildOfClass("Humanoid")local hd=ob.Head if hm.Health<=0 then continue end local sp,on=h:WorldToViewportPoint(hd.Position)if on then local ds=(Vector2.new(sp.X,sp.Y)-mp).Magnitude if ds<sh then sh=ds cl=hd end end end end return cl end
b.RenderStepped:Connect(function()FOV.Position=c:GetMouseLocation()FOV.Radius=S.Aimbot and S.AimbotFOV or S.NPCAimbotFOV FOV.Visible=S.Aimbot or S.NPCAimbot if S.Aimbot and c:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)then local t=GCP()if t then h.CFrame=h.CFrame:Lerp(CFrame.new(h.CFrame.Position,t.Position),S.AimbotSmooth)end end if S.NPCAimbot and c:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)then local t=GCN()if t then h.CFrame=h.CFrame:Lerp(CFrame.new(h.CFrame.Position,t.Position),0.14)end end end)
local function CE(pl)if ESPO[pl]then return end local t={Box=Drawing.new("Square"),Name=Drawing.new("Text"),Health=Drawing.new("Text"),Distance=Drawing.new("Text"),Tracer=Drawing.new("Line")}t.Box.Thickness=1.2 t.Box.Filled=false t.Box.Color=Color3.fromRGB(0,200,255)t.Name.Size=14 t.Name.Center=true t.Name.Outline=true t.Name.Color=Color3.fromRGB(255,255,255)t.Health.Size=12 t.Health.Center=true t.Health.Outline=true t.Distance.Size=12 t.Distance.Center=true t.Distance.Outline=true t.Distance.Color=Color3.fromRGB(200,200,200)t.Tracer.Thickness=1.2 t.Tracer.Color=Color3.fromRGB(0,180,255)ESPO[pl]=t end
