b.RenderStepped:Connect(function()if not S.ESP then for _,t in pairs(ESPO)do for _,d in pairs(t)do d.Visible=false end end return end for _,pl in ipairs(a:GetPlayers())do if pl==g then continue end if S.ESPTeamCheck and pl.Team==g.Team then if ESPO[pl]then for _,d in pairs(ESPO[pl])do d.Visible=false end end continue end CE(pl)local t=ESPO[pl]local ch=pl.Character if not ch or not ch:FindFirstChild("HumanoidRootPart")or not ch:FindFirstChildOfClass("Humanoid")or ch.Humanoid.Health<=0 then for _,d in pairs(t)do d.Visible=false end continue end local rt=ch.HumanoidRootPart local hm=ch.Humanoid local pos,on=h:WorldToViewportPoint(rt.Position)local ds=(rt.Position-h.CFrame.Position).Magnitude if not on or ds>S.ESPMaxDist then for _,d in pairs(t)do d.Visible=false end continue end local sc=math.clamp(1000/pos.Z,0.3,4)local sz=Vector2.new(34*sc,52*sc)t.Box.Size=sz t.Box.Position=Vector2.new(pos.X-sz.X/2,pos.Y-sz.Y/2)t.Box.Visible=S.ESPBox t.Name.Text=pl.Name t.Name.Position=Vector2.new(pos.X,pos.Y-sz.Y/2-15)t.Name.Visible=S.ESPName t.Health.Text=math.floor(hm.Health).." HP"t.Health.Position=Vector2.new(pos.X,pos.Y+sz.Y/2+2)t.Health.Color=Color3.fromRGB(255-(hm.Health/hm.MaxHealth)*255,(hm.Health/hm.MaxHealth)*255,0)t.Health.Visible=S.ESPHealth t.Distance.Text=math.floor(ds).."m"t.Distance.Position=Vector2.new(pos.X,pos.Y+sz.Y/2+15)t.Distance.Visible=S.ESPDistance t.Tracer.From=Vector2.new(h.ViewportSize.X/2,h.ViewportSize.Y)t.Tracer.To=Vector2.new(pos.X,pos.Y+sz.Y/2)t.Tracer.Visible=S.ESPTracer end end)
